-- Migration: les exercices systeme en anglais
--
-- Les exercices systeme sont ecrits en base, en francais. Plutot que de
-- dupliquer les lignes par langue (la progression de chacun pointe sur
-- l'id de l'exercice), chaque exercice porte ses traductions :
--   translations = {"en": {"name", "description", "instructions", "tips"}}
-- getExercises() les applique selon la langue de l'utilisateur ; un
-- exercice cree par un musicien reste dans la langue ou il l'a ecrit.

ALTER TABLE exercises
  ADD COLUMN IF NOT EXISTS translations JSONB NOT NULL DEFAULT '{}';

UPDATE exercises AS e
SET translations = e.translations || jsonb_build_object('en', v.en)
FROM (VALUES
  ('Gamme pentatonique mineure', '{"name": "Minor pentatonic scale", "description": "The most used scale in rock and blues. Position 1 in A.", "instructions": ["Start in position 1 (5th fret in A)", "Play each note as eighth notes", "Go up then down the scale", "Keep your fingers close to the neck"], "tips": ["Use a metronome", "Focus on evenness", "Relax your fretting hand"]}'::jsonb),
  ('Gamme majeure - 3 octaves', '{"name": "Major scale - 3 octaves", "description": "Major scale along the whole length of the neck.", "instructions": ["Start from the low root", "Go up three octaves", "Use the 1-2-4 or 1-3-4 fingering", "Come back down the same way"], "tips": ["Work slowly at first", "Visualize the positions", "Listen for intonation"]}'::jsonb),
  ('Arpèges majeurs', '{"name": "Major arpeggios", "description": "Arpeggios of the basic major chords: C, G, D.", "instructions": ["Start with the C arpeggio", "Play root - third - fifth", "Move on to the G and D arpeggios", "Keep a steady tempo"], "tips": ["Let the notes ring", "Work on a clean sound"]}'::jsonb),
  ('Arpèges sweep picking', '{"name": "Sweep picking arpeggios", "description": "Sweep technique for fast three-string arpeggios.", "instructions": ["Three-string arpeggio shape", "Smooth pick motion", "One single downward or upward stroke", "Sync your picking and fretting hands"], "tips": ["The motion must be fluid", "Mute the strings you don''t play"]}'::jsonb),
  ('Alternate picking', '{"name": "Alternate picking", "description": "The fundamental alternating pick technique.", "instructions": ["One single string", "Alternate down-up-down-up", "Keep your wrist relaxed", "Gradually raise the tempo"], "tips": ["The motion comes from the wrist", "Keep it as small as possible"]}'::jsonb),
  ('Economy picking', '{"name": "Economy picking", "description": "Economical picking for fast runs across several strings.", "instructions": ["Change strings in the direction of the pick", "Minimize your movements", "Work on three adjacent strings"], "tips": ["Plan the pick direction", "Keep your hand relaxed"]}'::jsonb),
  ('Changements accords ouverts', '{"name": "Open chord changes", "description": "Smooth changes between open chords: Em - G - D - C.", "instructions": ["Progression: Em - G - D - C", "Four beats per chord", "Anticipate the next shape", "Move your fingers together"], "tips": ["Don''t look at the neck", "Build muscle memory"]}'::jsonb),
  ('Changements barrés', '{"name": "Barre chord changes", "description": "Moving between barre chords: F - Bb - C.", "instructions": ["F - Bb - C (barre shapes)", "Keep the barre shape", "Slide along the neck", "Keep the pressure even"], "tips": ["Press firmly with your thumb", "Place the barre close to the fret"]}'::jsonb),
  ('Pattern PIMA basique', '{"name": "Basic PIMA pattern", "description": "A fundamental fingerpicking pattern for beginners.", "instructions": ["P = thumb (bass), I = index, M = middle, A = ring", "Pattern: P-I-M-A-M-I", "Start on a C chord", "Keep your picking hand steady"], "tips": ["Keep your fingers above the strings", "Don''t pull the strings upward"]}'::jsonb),
  ('Travis picking', '{"name": "Travis picking", "description": "The alternating-bass technique made popular by Merle Travis.", "instructions": ["The thumb alternates between two bass strings", "The fingers play the melody", "Independence between the hands", "Start very slowly"], "tips": ["Your thumb is the metronome", "Practice each hand separately"]}'::jsonb),
  ('Hammer-ons et pull-offs', '{"name": "Hammer-ons and pull-offs", "description": "Legato technique for smooth slurs.", "instructions": ["Hammer-on: strike the string with your finger", "Pull-off: pluck slightly as you release", "1-2-3-4 exercise on one string", "Keep the volume even"], "tips": ["The force comes from the finger, not the arm", "Keep your fingers close to the frets"]}'::jsonb),
  ('Bends et vibratos', '{"name": "Bends and vibrato", "description": "Expression and pitch accuracy in bends.", "instructions": ["Bend a whole step, then a half step", "Check the pitch against the target note", "Vibrato: an even oscillation", "Drive it from the wrist"], "tips": ["Support with the neighboring fingers", "Vibrato should sound musical"]}'::jsonb),
  ('Strumming patterns', '{"name": "Strumming patterns", "description": "Essential rhythm patterns for accompaniment.", "instructions": ["Pattern 1: D D D D (quarter notes)", "Pattern 2: D D U U D U", "Pattern 3: D U D U D U D U (eighth notes)", "Keep your arm moving constantly"], "tips": ["Your arm never stops", "Accent the strong beats"]}'::jsonb),
  ('Syncopes et ghost notes', '{"name": "Syncopation and ghost notes", "description": "Advanced funk rhythms with ghost notes.", "instructions": ["Accent the offbeats", "Ghost notes: barely touch the strings", "Funk rhythm patterns", "Practice with a backing track"], "tips": ["Listen to a lot of funk", "The groove is in the placement"]}'::jsonb),
  ('Single stroke roll', '{"name": "Single stroke roll", "description": "The basic rudiment: one hand after the other, perfectly even.", "instructions": ["On a pad or the snare, play R L R L as sixteenth notes", "Both sticks start from the same height", "Keep the same volume on every stroke", "Start again leading with the left hand"], "tips": ["Let the stick bounce, don''t bury it in the head", "Record yourself: both hands should sound the same", "Shoulders and wrists relaxed"]}'::jsonb),
  ('Double stroke roll', '{"name": "Double stroke roll", "description": "Two strokes per hand, the roll that smooths out everything else.", "instructions": ["Play R R L L as sixteenth notes", "Each hand''s second stroke must be as loud as the first", "Start slowly with two real wrist strokes", "As you speed up, let the rebound play the second stroke"], "tips": ["The second stroke is often too weak: accent it on purpose", "Also practice it as triplets (R R L L R R over two beats)"]}'::jsonb),
  ('Paradiddle', '{"name": "Paradiddle", "description": "R L R R – L R L L: the rudiment that leads to grooves and fills.", "instructions": ["Play R L R R L R L L as sixteenth notes", "Accent the first note of each group", "Keep the unaccented notes low, close to the head", "Then move your right hand to the hi-hat to turn it into a groove"], "tips": ["Think \"high accents, low ghost notes\": the contrast is what matters", "Say the rudiment out loud at first"]}'::jsonb),
  ('Flam et flam tap', '{"name": "Flam and flam tap", "description": "Two sticks almost together: the grace note just before the main one.", "instructions": ["One stick low (grace note), the other high (main note)", "Both land almost together, the low one a hair earlier", "Alternate: right flam, left flam", "Then flam tap: a flam followed by a single stroke with the same hand"], "tips": ["If you hear one stroke, the stick heights are too close", "If you hear two distinct strokes, bring them closer"]}'::jsonb),
  ('Groove rock de base', '{"name": "Basic rock groove", "description": "Eighth notes on the hi-hat, kick on 1 and 3, snare on 2 and 4.", "instructions": ["Right hand: steady eighth notes on the closed hi-hat", "Right foot: kick on beats 1 and 3", "Left hand: snare on beats 2 and 4", "Loop four bars without stopping"], "tips": ["The hi-hat must stay perfectly even, even when the snare hits", "Count out loud \"1 and 2 and…\""]}'::jsonb),
  ('Groove shuffle', '{"name": "Shuffle groove", "description": "The triplet swing of blues and rock''n''roll.", "instructions": ["Count triplets: \"1 trip let 2 trip let\"", "Hi-hat on the first and third note of each triplet", "Snare on 2 and 4, kick on 1 and 3", "Then add ghost notes on the middle note"], "tips": ["Set the metronome to triplets to feel the subdivision", "A shuffle should swing, not rush"]}'::jsonb),
  ('Breaks d''un temps sur les toms', '{"name": "One-beat tom fills", "description": "Three bars of groove, a fill, and land right on the 1.", "instructions": ["Play three bars of the basic rock groove", "On the last beat of the fourth bar, four sixteenth notes on the toms", "Land on a crash cymbal + kick on beat 1", "Change the order of the toms each time around"], "tips": ["The fill must neither speed up nor slow down the tempo", "What matters most is landing on the 1"]}'::jsonb),
  ('Indépendance : grosse caisse libre', '{"name": "Independence: free kick drum", "description": "The right hand stays put, the foot moves around.", "instructions": ["Eighth notes on the hi-hat and snare on 2 and 4, on a loop", "Place the kick on the \"and\" of 2, then of 3, then of 4", "One variation per four-bar line", "Finish by combining two placements"], "tips": ["If the hi-hat stumbles, slow down: it''s your reference", "Write down your favorite variations to reuse them"]}'::jsonb),
  ('Double pédale en doubles croches', '{"name": "Double bass sixteenth notes", "description": "Stamina and evenness in both feet.", "instructions": ["Right foot, left foot as steady sixteenth notes", "One bar playing, one bar resting", "Then four bars in a row", "Add a snare on 2 and 4 on top"], "tips": ["Play with the ball of the foot, heel up", "Set the spring tension the same on both sides"]}'::jsonb),
  ('Gamme majeure sur deux octaves', '{"name": "Two-octave major scale", "description": "The reference scale, in one position and then moving around.", "instructions": ["Start from the root on the E string (e.g. G, 3rd fret)", "1-2-4 / 1-2-4 / 1-3-4 fingering, one finger per fret", "Go up then down in eighth notes", "Change key with each set"], "tips": ["Alternate index and middle on your plucking hand, never repeating the same finger", "Mute the low strings with your thumb"]}'::jsonb),
  ('Pentatonique mineure en boîte', '{"name": "Minor pentatonic box", "description": "The scale behind rock, blues and funk lines.", "instructions": ["Play the A minor pentatonic from the 5th fret", "Up and down in eighth notes", "Then in groups of three notes", "Improvise a simple line on two notes of the scale"], "tips": ["Aim for the root on beat 1", "Let it ring, don''t cut the notes too soon"]}'::jsonb),
  ('Fondamentale en croches, calée au clic', '{"name": "Root eighth notes, locked to the click", "description": "The core of the bassist''s job: holding the tempo with the drummer.", "instructions": ["Steady eighth notes on the root: A, D, E, one bar each", "Set the metronome to play only on 2 and 4 (silent mode)", "Try to land right on the click", "Vary the note lengths: legato, then staccato"], "tips": ["Evenness matters more than the notes", "Listen to the end of each note as much as its start"]}'::jsonb),
  ('Fondamentale, quinte, octave', '{"name": "Root, fifth, octave", "description": "The pattern that works over almost any progression.", "instructions": ["Root on 1, fifth on 2, octave on 3, fifth on 4", "Play it over a C – A minor – F – G progression", "Keep the same fingering as you move your hand", "Then make up a rhythmic variation"], "tips": ["The fifth is one fret higher on the next higher string, the octave two frets higher two strings up"]}'::jsonb),
  ('Alternance index-majeur', '{"name": "Index-middle alternation", "description": "A steady plucking hand, the foundation of fingerstyle playing.", "instructions": ["On an open string, alternate index and middle in eighth notes, then sixteenths", "Both fingers must sound the same", "Change strings without breaking the alternation", "Finish on a scale"], "tips": ["Let your finger rest on the next lower string (rest stroke)", "No volume jumps between fingers"]}'::jsonb),
  ('Arpèges de triades et de septièmes', '{"name": "Triad and seventh arpeggios", "description": "Know the chord tones to build your lines.", "instructions": ["Major triad: root, third, fifth, octave", "Minor triad, then seventh chords (maj7, 7, m7)", "One bar per chord, in quarter notes then eighth notes", "Play them over a II – V – I progression"], "tips": ["Say each note''s name as you play it", "Keep the same hand shape as you change keys"]}'::jsonb),
  ('Slap : pouce et pop', '{"name": "Slap: thumb and pop", "description": "The funk sound: thumb on the low strings, pop on the high ones.", "instructions": ["Thumb on the open E string, eighth notes, bouncing quickly off the string", "Index pulls the G string (pop) on beats 2 and 4", "Add the octave: thumb on the root, pop on the octave", "Add fretting-hand muted notes in between"], "tips": ["The thumb strikes near the end of the fretboard and bounces right off", "Pop without yanking: just enough to snap"]}'::jsonb),
  ('Walking bass sur un blues', '{"name": "Walking bass over a blues", "description": "Four quarter notes per bar walking from one chord to the next.", "instructions": ["Twelve-bar blues in F", "Root on beat 1 of every bar", "Fill in with chord and scale tones", "Beat 4 leads into the next chord: a half step above or below"], "tips": ["Think path, not scale: each bar leads to the next", "Lightly accent 2 and 4"]}'::jsonb),
  ('Ghost notes et étouffés', '{"name": "Ghost notes and muted notes", "description": "The percussive notes that give a line its groove.", "instructions": ["Sixteenth-note line: root, muted, muted, octave", "Rest your fretting hand on the strings without pressing for the muted notes", "Keep your plucking hand moving constantly", "Move the line over a two-chord progression"], "tips": ["Ghost notes should be heard, not played loud", "Listen to Rocco Prestia or James Jamerson for the feel"]}'::jsonb),
  ('Gamme de Do majeur, mains séparées puis ensemble', '{"name": "C major scale, hands separately then together", "description": "The basic fingering over one octave, then two.", "instructions": ["Right hand: 1-2-3, thumb under, 1-2-3-4-5", "Left hand: 5-4-3-2-1, 3 over, 3-2-1", "Each hand alone, then both together", "Move to two octaves once it''s even"], "tips": ["Prepare the thumb-under ahead of time, without lifting your elbow", "Every note should sound at the same volume"]}'::jsonb),
  ('Gammes majeures en cycle des quintes', '{"name": "Major scales around the circle of fifths", "description": "C, G, D, A… every key, one a day.", "instructions": ["One key a day, following the circle of fifths", "Two octaves, hands together, in eighth notes", "Then in sixteenth notes at half the tempo", "Name the sharps or flats before you start"], "tips": ["Fingerings change from key to key: check them before playing fast"]}'::jsonb),
  ('Arpèges de triades', '{"name": "Triad arpeggios", "description": "Chords spread out over one or two octaves.", "instructions": ["Right hand: C – E – G – C, fingers 1-2-3-5", "Go up and down one octave, then two", "Do the same with the left hand (5-3-2-1)", "Play C, F, G, A minor in a row"], "tips": ["Let your wrist follow the sideways motion, loosely"]}'::jsonb),
  ('Renversements d''accords', '{"name": "Chord inversions", "description": "Move from chord to chord without jumping around the keyboard.", "instructions": ["Play C major in root position, then 1st and 2nd inversion", "Play C – F – G – C keeping the common notes", "Always choose the closest inversion", "Accompany a simple melody with these shapes"], "tips": ["The less your hand moves, the smoother the progression sounds"]}'::jsonb),
  ('II – V – I avec voicings sans fondamentale', '{"name": "II – V – I with rootless voicings", "description": "The basic jazz progression, with pianist voicings.", "instructions": ["Dm7 – G7 – Cmaj7: the third and seventh of each chord in the left hand", "The right hand adds the ninth and the fifth", "One bar per chord, then two chords per bar", "Transpose into three other keys"], "tips": ["The seventh of one chord falls a half step to the third of the next: listen for it"]}'::jsonb),
  ('Basse en octaves, accords à droite', '{"name": "Octave bass, chords in the right hand", "description": "The pop accompaniment pattern: the left hand keeps time.", "instructions": ["Left hand: root in octaves on 1 and 3", "Right hand: block chords in eighth notes", "Progression C – G – A minor – F", "Then a syncopated rhythm in the right hand"], "tips": ["If your left hand follows your right, slow down: each keeps its own rhythm"]}'::jsonb),
  ('Hanon n°1', '{"name": "Hanon No. 1", "description": "The classic exercise for even, independent fingers.", "instructions": ["Play the pattern C-E-F-G-A-G-F-E as sixteenth notes", "Move up one note with each repetition over two octaves", "Come back down with the reversed pattern", "Hands together, an octave apart"], "tips": ["Curved fingers, steady wrist", "Stop as soon as your hand tenses up"]}'::jsonb),
  ('Polyrythmie 3 contre 2', '{"name": "3 against 2 polyrhythm", "description": "One hand in triplets, the other in eighth notes.", "instructions": ["Left hand: two notes per beat", "Right hand: three notes per beat", "Say \"nice-cup-of-tea\" to place the notes", "Swap hands"], "tips": ["Start by tapping on your knees before the keyboard"]}'::jsonb),
  ('Lecture à vue quotidienne', '{"name": "Daily sight-reading", "description": "A new piece every day, without stopping.", "instructions": ["Pick an easy piece you''ve never played", "Spot the key, the time signature and the tricky passages before playing", "Play it once all the way through, without stopping on mistakes", "Do it again the next day with another piece"], "tips": ["Look at the next bar while you play this one", "A wrong note is better than breaking the tempo"]}'::jsonb),
  ('Clic sur 2 et 4', '{"name": "Click on 2 and 4", "description": "The metronome only plays the backbeats: you carry the time.", "instructions": ["Set the metronome to sound only on beats 2 and 4 (silent mode)", "Play a simple line or groove over it", "Feel 1 and 3 without hearing them", "Then play a whole song like that"], "tips": ["Snap your fingers on the click at first to lock in"]}'::jsonb),
  ('Mesures muettes', '{"name": "Silent bars", "description": "The click drops out every other bar: you have to land back on it.", "instructions": ["One bar with the metronome, one bar without (silent mode)", "Keep playing through the silent bar", "Check that you land right on the click", "Move to two silent bars out of four"], "tips": ["If you come in early, you''re speeding up without noticing: that''s normal at first"]}'::jsonb),
  ('Subdivisions', '{"name": "Subdivisions", "description": "Eighth notes, triplets, sixteenth notes without changing the tempo.", "instructions": ["One bar of quarter notes, one of eighths, one of triplets, one of sixteenths", "Loop without stopping", "Keep exactly the same underlying tempo", "Then in reverse order"], "tips": ["Going from eighths to triplets is the trickiest: count it out loud"]}'::jsonb)
) AS v(name, en)
WHERE e.is_system = TRUE AND e.name = v.name;
